-- Política de Privacidad: la analítica ahora guarda la IP y la ubicación aproximada de cada sesión
-- (migración 059). Reemplaza solo el párrafo "Analítica de uso" sembrado en la 051: si un
-- super_admin ya lo editó desde Configuración, el texto no coincide y no se toca.
UPDATE configuracion
SET valor = replace(valor, $viejo$Analítica de uso: Para entender cómo se usa la plataforma y mejorarla, VIGIIAP registra de forma completamente anónima las páginas visitadas (ruta, tipo de dispositivo, navegador y sitio de referencia). Este registro nunca incluye su dirección IP ni su identidad, ni siquiera si tiene una sesión iniciada -- no es posible vincular esta información a una persona.$viejo$, $nuevo$Analítica de uso: Para entender cómo se usa la plataforma y mejorarla, VIGIIAP registra las páginas visitadas (ruta, tipo de dispositivo, navegador y sitio de referencia) junto con la dirección IP y la ubicación aproximada (país, departamento y ciudad) que se deduce de ella con una base local, sin compartirla con terceros. Este registro no incluye su identidad ni se vincula a su cuenta, aunque tenga una sesión iniciada. La dirección IP se elimina automáticamente a los 90 días y el resto de la información de la sesión a los 2 años.$nuevo$)
WHERE clave = 'politicaPrivacidad'
  AND position($viejo$Analítica de uso: Para entender cómo se usa la plataforma y mejorarla, VIGIIAP registra de forma completamente anónima las páginas visitadas (ruta, tipo de dispositivo, navegador y sitio de referencia). Este registro nunca incluye su dirección IP ni su identidad, ni siquiera si tiene una sesión iniciada -- no es posible vincular esta información a una persona.$viejo$ in valor) > 0;
